saveModalDocuments = function () {
                var status = document.getElementById('kmedUploadStatus');
                if (!modalFiles.length) { status.textContent = 'Please select at least one document.'; status.style.display = 'block'; return; }
                for (var i = 0; i < modalFiles.length; i++) { if (!modalFiles[i].date) { status.textContent = 'Please select Test Done On for ' + modalFiles[i].file.name + '.'; status.style.display = 'block'; return; } }
                var form = new FormData(); form.append('method', 'savePendingDocuments'); form.append('ownerType', uploadOwnerType); form.append('ownerId', String(uploadOwnerId));
                modalFiles.forEach(function (item, i) { form.append('files', item.file, item.file.name); form.append('documentTypeId_' + i, item.typeId || ''); form.append('testDate_' + i, item.date || ''); form.append('note_' + i, item.note || ''); });
                var btn = document.getElementById('kmedSaveDocumentsButton'); btn.disabled = true; btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Saving...'; status.style.display = 'none';
                $.ajax({
                    url: uploadEndpoint, type: 'POST', data: form, processData: false, contentType: false, dataType: 'json', success: function (r) {
                        if (r && r.saved > 0) {
                            var savedNames = r.savedFiles || [];
                            modalFiles = modalFiles.filter(function (item) { return savedNames.indexOf(item.file.name) < 0; });
                            if (r.success) {
                                var successBox = document.getElementById('kmedUploadSuccess');
                                successBox.textContent = r.saved + ' document(s) saved successfully!';
                                successBox.style.display = 'block';
                                modalFiles = [];
                                renderModalFiles();
                            }
                            else { renderModalFiles(); status.textContent = r.message || ('Saved ' + r.saved + ' document(s); please retry the remaining files.'); status.style.display = 'block'; }
                        } else { status.textContent = (r && r.message) || 'Unable to save documents. Please try again.'; status.style.display = 'block'; }
                    }, error: function (xhr) { status.textContent = 'Upload failed. Please check the file size and try again.'; status.style.display = 'block'; }, complete: function () { btn.disabled = false; btn.innerHTML = '<i class="fa fa-cloud-upload-alt"></i> Save Document'; }
                });
            }
